	@ParameterizedTest
	@MethodSource("scenarios")
	void contextCountChannelsMatchTheIndependentGenericBag(Scenario scenario) {
		ValueFactory vf = repository.getValueFactory();
		StatementPattern pattern = new StatementPattern(scenario.scope(), Var.of("s"), Var.of("p"), Var.of("o"),
				Var.of("g"));
		TupleExpr input = pattern;
		String graphBinding = "g";
		if (scenario.alias()) {
			graphBinding = "alias";
			input = new Extension(input, new ExtensionElem(Var.of("g"), graphBinding));
		}
		Group group = scenario.grouped() ? new Group(input, List.of("s")) : new Group(input);
		group.addGroupElement(new GroupElem("rows", new Count(Var.of("s"))));
		group.addGroupElement(new GroupElem("graphs", new Count(Var.of(graphBinding))));
		group.addGroupElement(new GroupElem("distinctGraphs", new Count(Var.of(graphBinding), true)));
		group.addGroupElement(new GroupElem("iriObjects", new Sum(new If(new IsURI(Var.of("o")),
				new ValueConstant(vf.createLiteral(1)), new ValueConstant(vf.createLiteral(0))))));

		try (var dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			assertThat(dataset).as("the fixture must expose a real native source")
					.isInstanceOf(NativeLmdbQuerySource.class);
			var triples = new SailDatasetTripleTermSource(vf, dataset);
			QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
			DefaultEvaluationStrategy generic = new DefaultEvaluationStrategy(triples, null);
			List<BindingSet> expected = evaluate(generic.precompile(group.clone(), context));
			assertThat(rows(expected)).as("independent generic evaluation admits the exact expected bag: " + scenario)
					.containsExactlyInAnyOrderElementsOf(scenario.expected());

			LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(triples, null, null, 0L,
					new EvaluationStatistics(), false);
			QueryEvaluationStep candidate = LmdbNativeCensusAggregate.tryCreate(group,
					(NativeLmdbQuerySource) dataset, strategy, context, group,
					ignored -> ContextConstraint.UNRESTRICTED);
			assertThat(candidate).as("the existing finite-kind SUM channel admits census: " + scenario)
					.isInstanceOf(LmdbNativeCensusAggregate.class);
			assertThat(rows(evaluate(candidate))).as("native census must preserve the full generic bag: " + scenario)
					.containsExactlyInAnyOrderElementsOf(rows(expected));
		}
	}

	@ParameterizedTest
	@MethodSource("prevaluedFieldScenarios")
	void prevaluedPatternFieldsPreserveTheirGenericBoundness(PrevaluedFieldScenario scenario) {
		ValueFactory vf = repository.getValueFactory();
		Value value = vf.createIRI(EX + scenario.term());
		Var subject = Var.of("s");
		Var predicate = Var.of("p");
		Var object = Var.of("o");
		Var field = Var.of(scenario.name(), value, false, scenario.constant());
		switch (scenario.name()) {
		case "s" -> subject = field;
		case "p" -> predicate = field;
		case "o" -> object = field;
		default -> throw new IllegalArgumentException("unexpected prevalued field: " + scenario.name());
		}
		StatementPattern pattern = new StatementPattern(StatementPattern.Scope.DEFAULT_CONTEXTS, subject, predicate,
				object, Var.of("g"));
		Group group = new Group(pattern);
		group.addGroupElement(new GroupElem("observed", new Count(Var.of(scenario.name()))));
		group.addGroupElement(new GroupElem("iriObjects", new Sum(new If(new IsURI(Var.of("o")),
				new ValueConstant(vf.createLiteral(1)), new ValueConstant(vf.createLiteral(0))))));

		try (var dataset = NativeQuerySourceAccess.openExplicitDataset(store)) {
			assertThat(dataset).as("the field-boundness fixture must use a real native source")
					.isInstanceOf(NativeLmdbQuerySource.class);
			NativeLmdbQuerySource source = (NativeLmdbQuerySource) dataset;
			int position = switch (scenario.name()) {
			case "s" -> TripleIndex.SUBJ_IDX;
			case "p" -> TripleIndex.PRED_IDX;
			case "o" -> TripleIndex.OBJ_IDX;
			default -> throw new IllegalArgumentException("unexpected prevalued field: " + scenario.name());
			};
			assertThat(source.idOf(value, 1 << position))
					.as("the fixed term must be present in the corresponding source field")
					.isNotEqualTo(NativeLmdbQuerySource.UNKNOWN_ID);

			var triples = new SailDatasetTripleTermSource(vf, dataset);
			QueryEvaluationContext context = new QueryEvaluationContext.Minimal((Dataset) null);
			DefaultEvaluationStrategy generic = new DefaultEvaluationStrategy(triples, null);
			List<BindingSet> input = evaluate(generic.precompile(pattern.clone(), context));
			int expectedInputRows = scenario.name().equals("p") ? 3 : 1;
			assertThat(input).as("the exact fixed term must admit every matching real input statement: " + scenario)
					.hasSize(expectedInputRows);
			assertThat(input.getFirst().hasBinding(scenario.name()))
					.as("only nonconstant optimizer-valued Vars are exported: " + scenario)
					.isEqualTo(!scenario.constant());

			List<BindingSet> expected = evaluate(generic.precompile(group.clone(), context));
			assertThat(expected).as("the generic aggregate control must return one global row: " + scenario)
					.hasSize(1);
			long expectedCount = ((Literal) expected.getFirst().getValue("observed")).longValue();
			assertThat(expectedCount).as("COUNT observes algebra bindings, not constant pattern operands: " + scenario)
					.isEqualTo(scenario.constant() ? 0L : expectedInputRows);

			LmdbNativeEvaluationStrategy strategy = new LmdbNativeEvaluationStrategy(triples, null, null, 0L,
					new EvaluationStatistics(), false);
			QueryEvaluationStep candidate = LmdbNativeCensusAggregate.tryCreate(group, source, strategy, context, group,
					ignored -> ContextConstraint.UNRESTRICTED);
			if (scenario.constant()) {
				assertThat(candidate)
						.as("census must decline when its closed reducer cannot represent the unbound output: "
								+ scenario)
						.isNull();
			} else {
				assertThat(candidate)
						.as("the SUM channel independently admits this optimizer-valued field: " + scenario)
						.isInstanceOf(LmdbNativeCensusAggregate.class);
				assertThat(evaluate(candidate)).as("census preserves the full generic aggregate bag: " + scenario)
						.containsExactlyInAnyOrderElementsOf(expected);
			}
		}
	}

